import os


class Config:
    # Random Seed for reproducibility
    SEED = 42

    # Directory Paths
    # Input data (Read-only)
    INPUT_DIR = "./input"
    TRAIN_CSV_PATH = os.path.join(INPUT_DIR, "train.csv")
    TEST_CSV_PATH = os.path.join(INPUT_DIR, "test.csv")

    # Metadata (Generated by previous step)
    METADATA_DIR = "./metadata"
    METADATA_TRAIN_PATH = os.path.join(METADATA_DIR, "train.csv")
    METADATA_VAL_PATH = os.path.join(METADATA_DIR, "val.csv")
    METADATA_TEST_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working Directory (For caching and model artifacts)
    WORKING_DIR = "./working/idea_21"
    CACHE_DIR = WORKING_DIR  # Alias

    # Cache File Names
    CACHE_TRAIN_DATA = "train_data.npz"
    CACHE_VAL_DATA = "val_data.npz"
    CACHE_TEST_DATA = "test_data.npz"
    CACHE_SCALERS = "scalers.npz"

    # Model Artifacts
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pt")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Data Constants
    ATOMIC_SPECIES = ["Al", "Ga", "In", "O"]
    NUM_SPECIES = len(ATOMIC_SPECIES)

    # Feature Dimensions
    # Atomic Stream:
    #   - One-hot encoding (4)
    #   - Centered coords (3)
    #   - Chemically-resolved nearest neighbor distances (4)
    ATOMIC_FEATURE_DIM = 4 + 3 + 4  # 11

    # Global Stream:
    #   - Lattice lengths (3)
    #   - Lattice angles (3)
    #   - Unit cell volume (1)
    #   - Atomic density (1)
    #   - Total atoms (1)
    #   - Stoichiometry (3: Al, Ga, In fractions)
    GLOBAL_FEATURE_DIM = 3 + 3 + 1 + 1 + 1 + 3  # 12

    # Model Hyperparameters
    HIDDEN_DIM_ATOMIC = 512  # Wide MLP for atomic stream
    HIDDEN_DIM_GLOBAL = 256  # High capacity for global stream
    HIDDEN_DIM_FUSION = 256  # Fusion layer dimension
    DROPOUT_RATE = 0.2

    # Training Hyperparameters
    BATCH_SIZE = 64
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    EPOCHS = 200
    PATIENCE = 20  # Early stopping patience

    # Preprocessing Constants
    # Placeholder value for distance when a species is not present in the crystal
    # This should be large enough to be distinct but not cause numerical instability
    INFINITE_DISTANCE_VAL = 20.0

    # Ensure working directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
